import pytest
from playwright.sync_api import Page, expect

# --- Generated by Intelligent Functional Tester (Mock Mode) ---
# Target: https://automationexercise.com

def test_homepage_loads(page: Page):
    """Test that the homepage loads with products visible."""
    page.goto("https://automationexercise.com")
    page.wait_for_load_state("networkidle")
    expect(page.locator("body")).to_be_visible()
    expect(page.locator(".features_items")).to_be_visible()

def test_login_page_renders(page: Page):
    """Test the login page renders input fields."""
    page.goto("https://automationexercise.com/login")
    expect(page.locator("input[data-qa=\"login-email\"]")).to_be_visible()
    expect(page.locator("input[data-qa=\"login-password\"]")).to_be_visible()
    expect(page.locator("button[data-qa=\"login-button\"]")).to_be_visible()

def test_login_invalid_credentials(page: Page):
    """Test login fails with wrong password."""
    page.goto("https://automationexercise.com/login")
    page.fill("input[data-qa=\"login-email\"]", "wrong@example.com")
    page.fill("input[data-qa=\"login-password\"]", "WrongPassword!")
    page.click("button[data-qa=\"login-button\"]")  
    expect(page.locator("p:has-text(\"Your email or password is incorrect!\")")).to_be_visible()
